go
package main

import (
	"database/sql"
	"fmt"
	"github.com/mattn/go-sqlite3"
)

func main() {
	// Connect to SQLite database
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		fmt.Printf("Error opening database: %v\n", err)
		return
	}
	defer db.Close()

	// Create users table
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS users (
			username TEXT PRIMARY KEY,
			password TEXT,
			userInfo TEXT
		);
	`)
	if err != nil {
		fmt.Printf("Error creating table: %v\n", err)
		return
	}

	// Insert test data
	_, err = db.Exec("INSERT INTO users VALUES ('testuser', 'testpass', 'Test User Info')")
	if err != nil {
		fmt.Printf("Error inserting data: %v\n", err)
		return
	}

	// Test cases
	tests := []struct {
		username  string
		password  string
		expected  string
	}{
		{"testuser", "testpass", "Test User Info"},
		{"nonexistent", "wrongpass", ""},
	}

	for _, test := range tests {
		result := getUser(db, test.username, test.password)
		if result != test.expected {
			fmt.Printf("Test failed: username=%s, password=%s, expected=%s, got=%s\n",
				test.username, test.password, test.expected, result)
		} else {
			fmt.Printf("Test passed: username=%s, password=%s\n", test.username, test.password)
		}
	}
}
